def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    # Basic type check: ensure the object behaves like a time
    if not hasattr(value, "hour") or not hasattr(value, "minute") or not hasattr(value, "second"):
        raise TypeError(f"Expected a time-like object, got {type(value).__name__}")
    try:
        # Use ISO 8601 format which is safe for serialization
        return value.isoformat()
    except Exception as exc:
        raise ValueError(f"Failed to dehydrate time value: {exc}") from exc

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Prefer a dedicated _keys attribute if it exists and is a dict
        if hasattr(self, "_keys") and isinstance(self._keys, dict):
            return list(self._keys.keys())

        # Fallback to a 'data' attribute if present
        if hasattr(self, "data") and isinstance(self.data, dict):
            return list(self.data.keys())

        # As a last resort, return public attributes of the instance
        return [k for k in self.__dict__ if not k.startswith("_")]
    except Exception:
        # In case of any unexpected error, return an empty list
        return []

def index(self, key):
    """Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        # If self._index supports the list.index method
        if hasattr(self._index, "index"):
            return self._index.index(key)
        # Fallback: treat self._index as a mapping and search its keys
        return list(self._index.keys()).index(key)
    except (ValueError, KeyError, AttributeError):
        raise KeyError(f"Key not found: {key}") from None

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Assume the record stores field names in self._keys (list or tuple)
    # and values in self._values (list or tuple).
    if not hasattr(self, "_keys") or not hasattr(self, "_values"):
        raise AttributeError("Record object must have _keys and _values attributes")

    keys_list = list(keys)
    if not keys_list:
        # Return all fields
        return dict(zip(self._keys, self._values))

    result = {}
    for k in keys_list:
        if isinstance(k, int):
            # Index-based lookup
            if k < 0 or k >= len(self._values):
                raise IndexError(f"Index {k} out of bounds for record with {len(self._values)} values")
            field_name = self._keys[k]
            result[field_name] = self._values[k]
        elif isinstance(k, str):
            # Key-based lookup
            if k in self._keys:
                idx = self._keys.index(k)
                result[k] = self._values[idx]
            else:
                result[k] = None
        else:
            raise TypeError(f"Key {k!r} must be an int or str, not {type(k).__name__}")
    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
        """
        Appends a DISCARD message to the output queue.

        :param n: number of records to discard, default = -1 (ALL)
        :param qid: query ID to discard for, default = -1 (last query)
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        """
        # Validate numeric parameters
        if not isinstance(n, int):
            raise ValueError("n must be an integer")
        if not isinstance(qid, int):
            raise ValueError("qid must be an integer")
        if n < -1:
            raise ValueError("n must be >= -1")
        if qid < -1:
            raise ValueError("qid must be >= -1")

        # Normalize hooks
        dehydration_hooks = dehydration_hooks or {}
        hydration_hooks = hydration_hooks or {}

        # Validate hooks
        if not isinstance(dehydration_hooks, dict):
            raise ValueError("dehydration_hooks must be a dict")
        for typ, func in dehydration_hooks.items():
            if not isinstance(typ, type):
                raise ValueError("dehydration_hooks keys must be types")
            if not callable(func):
                raise ValueError(f"dehydration hook for {typ} is not callable")

        if not isinstance(hydration_hooks, dict):
            raise ValueError("hydration_hooks must be a dict")
        for typ, func in hydration_hooks.items():
            if not isinstance(typ, type):
                raise ValueError("hydration_hooks keys must be types")
            if not callable(func):
                raise ValueError(f"hydration hook for {typ} is not callable")

        # Validate handlers
        for name, handler in handlers.items():
            if not callable(handler):
                raise ValueError(f"handler '{name}' is not callable")

        # Construct the DISCARD message
        message = {
            "command": "DISCARD",
            "n": n,
            "qid": qid,
            "dehydration_hooks": dehydration_hooks,
            "hydration_hooks": hydration_hooks
        }

        # Append to the output queue
        try:
            self._output_queue.put(message, block=False)
        except Exception as exc:
            raise RuntimeError(f"Failed to enqueue DISCARD message: {exc}") from exc

        # Return a Response object that can accept handlers
        try:
            return Response(message, **handlers)
        except Exception as exc:
            raise RuntimeError(f"Failed to create Response: {exc}") from exc

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate class name
    if not isinstance(name, str) or not name.isidentifier():
        raise TypeError(f"Invalid class name: {name!r}")

    # Validate fields iterable and collect field names
    try:
        field_names = list(fields)
    except Exception as exc:
        raise TypeError("fields must be an iterable of field names") from exc

    seen = set()
    for f in field_names:
        if not isinstance(f, str) or not f.isidentifier():
            raise TypeError(f"Invalid field name: {f!r}")
        if f in seen:
            raise TypeError(f"Duplicate field name: {f!r}")
        seen.add(f)

    # Validate srid_map
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dict")

    # Ensure the base Point class is available
    try:
        base = Point
    except NameError as exc:
        raise NameError("Base class 'Point' is not defined") from exc

    # Build the namespace for the new class
    namespace = {"__module__": __name__}
    for f in field_names:
        namespace[f] = None  # default value; can be overridden by subclasses
    namespace["srid_map"] = srid_map
    namespace["__doc__"] = f"Point subclass {name} with fields {', '.join(field_names)}"

    # Create and return the new subclass
    return type(name, (base,), namespace)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """

    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    if maxsize <= 0:
        # No caching; return the original function unchanged
        def _no_cache(fn):
            def wrapper(*args, **kwargs):
                return fn(*args, **kwargs)
            wrapper.__name__ = fn.__name__
            wrapper.__doc__ = fn.__doc__
            wrapper.__module__ = fn.__module__
            wrapper.__annotations__ = fn.__annotations__
            return wrapper
        return _no_cache

    def decorator(fn):
        cache = {}
        order = []

        def make_key(args, kwargs, typed):
            # Build a hashable key from args and kwargs
            key = args
            if kwargs:
                # Sort kwargs to ensure consistent ordering
                items = tuple(sorted(kwargs.items()))
                key += items
            if typed:
                # Include types in the key
                key = tuple((arg, type(arg)) for arg in args)
                if kwargs:
                    key += tuple((k, type(v), v) for k, v in sorted(kwargs.items()))
            return key

        def wrapper(*args, **kwargs):
            try:
                key = make_key(args, kwargs, typed)
            except Exception:
                # If key creation fails (e.g., unhashable arguments), skip caching
                return fn(*args, **kwargs)

            if key in cache:
                # Move key to the end to mark it as recently used
                try:
                    order.remove(key)
                except ValueError:
                    pass
                order.append(key)
                return cache[key]

            # Compute the function result and store it
            result = fn(*args, **kwargs)
            cache[key] = result
            order.append(key)

            # Evict least recently used item if cache exceeds maxsize
            if len(cache) > maxsize:
                oldest = order.pop(0)
                cache.pop(oldest, None)

            return result

        # Preserve function metadata
        wrapper.__name__ = fn.__name__
        wrapper.__doc__ = fn.__doc__
        wrapper.__module__ = fn.__module__
        wrapper.__annotations__ = fn.__annotations__
        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        counts = {}
        order = collections.OrderedDict()

        def _make_key(args, kwargs, typed):
            if typed:
                key = (tuple((type(a), a) for a in args),
                       tuple((k, type(v), v) for k, v in sorted(kwargs.items())))
            else:
                key = (args, tuple(sorted(kwargs.items())))
            return key

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs, typed)
            if key in cache:
                counts[key] += 1
                return cache[key]
            result = func(*args, **kwargs)
            if maxsize is not None and len(cache) >= maxsize:
                # Find the key(s) with the lowest access count
                min_count = min(counts.values())
                # Evict the first key with the minimum count (FIFO tie‑break)
                for evict_key in order:
                    if counts[evict_key] == min_count:
                        break
                del cache[evict_key]
                del counts[evict_key]
                del order[evict_key]
            cache[key] = result
            counts[key] = 1
            order[key] = None
            return result

        return wrapper

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        # Python 3.8+ supports `last=False` to pop the first inserted item
        return dict.popitem(self, last=False)
    except TypeError:
        # Fallback for older Python versions that don't support `last` argument
        items = list(self.items())
        if not items:
            raise KeyError('dictionary is empty')
        key, value = items[0]
        del self[key]
        return key, value

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""
    storage = getattr(self, 'storage', None) or getattr(self, '_value', None)
    if storage is None:
        logger.error("setdefault: No storage attribute found")
        return None
    try:
        if key in storage:
            return storage[key]
        storage[key] = default
        return default
    except TypeError:
        logger.error(f"setdefault: Key {key!r} is not hashable")
        return None
    except Exception as e:
        logger.error(f"setdefault: Error setting default for key {key!r}: {e}")
        return None

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        return self[key]
    except KeyError:
        return default

