def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    # Basic input validation
    if graph is None:
        raise TypeError("graph must be an rdflib Graph instance")
    if prop is None:
        raise TypeError("prop must be a URIRef")
    if roots is not None and not isinstance(roots, set):
        # allow any iterable of nodes
        try:
            roots = set(roots)
        except Exception as exc:
            raise TypeError("roots must be a set or iterable of Nodes") from exc

    try:
        children = set()
        parents = set()
        for s, p, o in graph.triples((None, prop, None)):
            children.add(s)
            parents.add(o)

        # If a subset of roots was supplied, restrict the search to that subset
        if roots is not None:
            parents = parents.intersection(roots)

        # Roots are parents that never appear as a child
        return parents - children
    except Exception as exc:
        raise RuntimeError(f"Error while finding roots: {exc}") from exc

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        # Use SafeDumper by default if no dumper is provided
        if dumper is None:
            dumper = yaml.SafeDumper
        # Dump the object to a YAML string
        result = yaml.safe_dump(obj, Dumper=dumper, default_flow_style=False)
        # In Python 2, yaml.safe_dump may return a byte string; convert to unicode
        if isinstance(result, bytes):
            result = result.decode("utf-8")
        return result
    except Exception as exc:
        raise ValueError(f"Error dumping object to YAML string: {exc}") from exc

def make_array(shape, dtype=np.dtype("float32")):
    """Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate shape
    if not isinstance(shape, (tuple, list)):
        raise TypeError("shape must be a tuple or list of integers")
    try:
        shape_tuple = tuple(int(dim) for dim in shape)
    except Exception as e:
        raise ValueError("shape must contain integers") from e

    # Validate dtype
    if not isinstance(dtype, np.dtype):
        try:
            dtype = np.dtype(dtype)
        except Exception as e:
            raise TypeError("dtype must be a numpy dtype") from e

    # Create the array
    try:
        arr = np.empty(shape_tuple, dtype=dtype)
    except Exception as e:
        raise ValueError(f"Failed to create array with shape {shape_tuple} and dtype {dtype}") from e

    return arr

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    if isinstance(obj, str):
        try:
            return obj.encode('utf-8')
        except Exception as e:
            raise ValueError(f"Failed to encode string to UTF-8: {e}") from e
    elif isinstance(obj, (bytes, bytearray)):
        return obj
    else:
        return obj

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        raise TypeError("values must be an iterable of strings")
    bookmarks = []
    for v in values:
        if not isinstance(v, str):
            raise TypeError(f"Bookmark value must be a string, got {type(v).__name__}")
        try:
            # Prefer a dedicated parser if available
            bookmark = Bookmark.from_raw_value(v)
        except AttributeError:
            # Fallback to direct constructor
            bookmark = Bookmark(v)
        except Exception as exc:
            raise ValueError(f"Failed to parse bookmark from raw value '{v}': {exc}") from exc
        bookmarks.append(bookmark)
    return cls(bookmarks)

