def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Basic type checks
    if not isinstance(iface, type):
        raise TypeError(f"iface must be a type, got {type(iface).__name__}")
    if candidate is None:
        raise TypeError("candidate cannot be None")

    # Determine if candidate is a class or an instance
    candidate_cls = candidate if isinstance(candidate, type) else type(candidate)

    # Quick subclass / instance check
    try:
        if isinstance(candidate, type):
            if issubclass(candidate_cls, iface):
                return True
        else:
            if isinstance(candidate, iface):
                return True
    except Exception:
        # If issubclass or isinstance fails, fall back to attribute checks
        pass

    # Inspect attributes defined on the interface
    for name, attr in iface.__dict__.items():
        # Skip special/dunder attributes
        if name.startswith('__') and name.endswith('__'):
            continue
        # Skip private attributes
        if name.startswith('_'):
            continue
        # Check presence on candidate
        if not hasattr(candidate, name):
            if tentative:
                return False
            raise TypeError(
                f"Candidate missing required attribute '{name}' for interface '{iface.__name__}'"
            )
        # If the interface attribute is a function or method, ensure candidate's attribute is callable
        if callable(attr):
            candidate_attr = getattr(candidate, name)
            if not callable(candidate_attr):
                if tentative:
                    return False
                raise TypeError(
                    f"Attribute '{name}' of candidate is not callable as required by interface '{iface.__name__}'"
                )
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If no bases are provided, default to the built‑in type
    if not bases:
        return type

    # Validate that all bases are actual classes
    for b in bases:
        if not isinstance(b, type):
            raise TypeError(f"Base {b!r} is not a class")

    # If an explicit metaclass is supplied, it must be a subclass of all
    # base metaclasses
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"Explicit metaclass {explicit_mc!r} is not a class")
        for b in bases:
            if not issubclass(explicit_mc, type(b)):
                raise TypeError(
                    f"Explicit metaclass {explicit_mc.__name__} is not a subclass of "
                    f"base {b.__name__}'s metaclass {type(b).__name__}"
                )
        return explicit_mc

    # Determine the most derived metaclass from the bases
    metaclasses = [type(b) for b in bases]
    candidate = metaclasses[0]
    for mc in metaclasses[1:]:
        if issubclass(candidate, mc):
            # candidate is already a subclass of mc; keep it
            continue
        if issubclass(mc, candidate):
            # mc is more derived; adopt it
            candidate = mc
            continue
        # No common metaclass found
        raise TypeError(
            f"metaclass conflict: {candidate.__name__} and {mc.__name__} are incompatible"
        )
    return candidate

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is not __marker:
            return default
        raise KeyError(key)
    # Use dict.pop to avoid recursion
    return dict.pop(self, key)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Ensure the required attributes exist
    try:
        data = self._data
        freq = self._freq
    except AttributeError:
        raise AttributeError('Object must have `_data` and `_freq` attributes')

    if not data:
        raise KeyError('dict is empty')

    # Find the key with the lowest frequency
    try:
        min_key = min(freq, key=freq.get)
    except ValueError:
        # freq is empty but data is not; clean up and raise
        self._data.clear()
        self._freq.clear()
        raise KeyError('dict is empty')

    # Remove the key from both structures
    value = data.pop(min_key)
    freq.pop(min_key, None)

    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Ensure the underlying storage exists
    if not hasattr(self, "_cache"):
        raise AttributeError("LRU cache storage not initialized")
    try:
        # OrderedDict.popitem(last=False) removes the first (least recently used) item
        return self._cache.popitem(last=False)
    except KeyError:
        # The cache is empty
        raise KeyError("LRU cache is empty")

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # The most recently used item is stored right after the head sentinel.
    node = self._head[2]
    if node is self._tail:
        raise KeyError('list is empty')
    # Ensure we have the correct previous node reference before removal.
    self._find_lt(node[0])
    self._remove(node)
    return (node[0], node[1])

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if not self:
        raise KeyError('dict is empty')
    import random
    key = random.choice(list(self.keys()))
    value = self.pop(key)
    return (key, value)

def _create_in_regex(self) -> Pattern:
    """Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    # Use a default pattern if none provided
    pattern_str = getattr(self, "_in_pattern_str", r'\b(?P<field>\w+)\s+in\s*\((?P<values>[^)]*)\)')
    if not isinstance(pattern_str, str):
        raise TypeError("in pattern must be a string")
    try:
        return re.compile(pattern_str, flags=re.UNICODE | re.MULTILINE)
    except re.error as exc:
        raise ValueError(f"Invalid in-style regex pattern: {exc}") from exc

def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    try:
