    except Exception as exc:
        raise RuntimeError("Unable to instantiate parameter style converter") from exc

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    from datetime import datetime, timezone
    if dt is None:
        return None
    if not isinstance(dt, datetime):
        raise TypeError("dt must be a datetime instance")
    # Ensure timezone-aware; assume UTC for naive datetimes
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    # Use ISO 8601 format with seconds precision
    iso = dt.isoformat(timespec='seconds')
    # Convert UTC offset to 'Z' if applicable
    if iso.endswith('+00:00'):
        iso = iso[:-6] + 'Z'
    return iso

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags_set = set()
    new_lines = []
    inside_code = False

    for line in text.splitlines():
        # Toggle code block state when encountering a fence
        if '```' in line:
            inside_code = not inside_code

