def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    # Normalise the handle: strip the optional "acct:" prefix
    if handle.startswith("acct:"):
        handle = handle[5:]
    try:
        # Extract the host part of the handle
        host = handle.split("@")[1]
    except Exception:
        # Invalid handle format
        return None

    # Construct the webfinger URL
    url = f"https://{host}/.well-known/webfinger?resource=acct:{handle}"
    try:
        # Perform the HTTP GET request
        resp = urllib2.urlopen(url, timeout=10)
        try:
            # Only consider successful responses
            if resp.getcode() != 200:
                return None
            # Read and decode the response body
            data = resp.read()
            if isinstance(data, bytes):
                return data.decode("utf-8")
            return data
        finally:
            resp.close()
    except Exception:
        # Any network or parsing error results in None
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    if not host:
        return None
    try:
        document, code, exception = fetch_document(host=host, path="/.well-known/host-meta")
        if exception:
            return None
        return XRD.parse_xrd(document)
    except Exception:
        return None

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        # Normalize settings_dirs to a list
        dirs = (
            settings_dirs
            if isinstance(settings_dirs, (list, tuple))
            else [settings_dirs]
        )
        files = []
        for d in dirs:
            if not os.path.isdir(d):
                continue
            for fname in os.listdir(d):
                full_path = os.path.join(d, fname)
                if spec_option is None:
                    files.append(full_path)
                else:
                    if isinstance(spec_option, str):
                        if fname.endswith(spec_option):
                            files.append(full_path)
                    elif isinstance(spec_option, (list, tuple)):
                        if any(fname.endswith(ext) for ext in spec_option):
                            files.append(full_path)
                    elif callable(spec_option):
                        try:
                            if spec_option(fname):
                                files.append(full_path)
                        except Exception:
                            # Skip files that cause the predicate to fail
                            continue
        return sorted(files)
    except OSError:
        return []

