@classmethod
def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("spec_content must be provided")

    # Load YAML if a string is provided
    if isinstance(spec_content, str):
        try:
            spec = yaml.safe_load(spec_content)
        except Exception as e:
            raise IRValidatorException(f"Error parsing YAML: {e}")
    elif isinstance(spec_content, dict):
        spec = spec_content
    else:
        raise IRValidatorException("spec_content must be a YAML string or a dict")

    if not isinstance(spec, dict):
        raise IRValidatorException("Parsed spec is not a dictionary")

    # Define required fields (can be overridden by subclasses)
    required_fields = getattr(cls, "REQUIRED_FIELDS", ["name", "type", "spec"])
    missing = [field for field in required_fields if field not in spec]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")

    return spec

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise ValueError("yaml_file argument must be supplied")
        try:
            with open(yaml_file, "r") as f:
                data = yaml.safe_load(f)
        except Exception as e:
            raise IRValidatorException(f"Error loading YAML file {yaml_file}: {e}") from e
        if not isinstance(data, dict):
            raise IRValidatorException(f"YAML file {yaml_file} does not contain a mapping at the top level")
        required = getattr(cls, "REQUIRED_FIELDS", [])
        missing = [field for field in required if field not in data]
        if missing:
            raise IRValidatorException(f"Missing required fields in {yaml_file}: {', '.join(missing)}")
        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Helper to recursively resolve includes for a single parser
    def _resolve(name, seen):
        if name in seen:
            raise ValueError(f"Circular include detected: {' -> '.join(seen)} -> {name}")
        seen.add(name)
        parser = parser_dict.get(name)
        if parser is None:
            raise KeyError(f"Parser '{name}' not found for include")
        if 'include' in parser:
            inc = parser['include']
            # Normalize to a list of names
            if isinstance(inc, str):
                inc_names = [inc]
            elif isinstance(inc, (list, tuple)):
                inc_names = list(inc)
            else:
                raise TypeError(f"Unsupported include type for parser '{name}': {type(inc)}")
            for inc_name in inc_names:
                inc_parser = _resolve(inc_name, seen.copy())
                # Merge included parser into current parser
                for k, v in inc_parser.items():
                    if k not in parser or k == 'include':
                        parser[k] = v
            # Remove the include key after merging
            parser.pop('include', None)
        return parser

    # Resolve all parsers in the dictionary
    for pname in list(parser_dict.keys()):
        _resolve(pname, set())
    # No explicit return; parser_dict is modified in place.

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Ensure we have a list of arguments to process
    args = getattr(self, "args", [])
    if not args:
        return defaults

    # Helper to fetch a value from a spec-like object
    def _fetch(spec_obj, name):
        if spec_obj is None:
            return None
        # Try dict-like access first
        try:
            return spec_obj.get(name)
        except AttributeError:
            pass
        # Fallback to attribute access
        return getattr(spec_obj, name, None)

    for arg in args:
        # Skip non-option objects
        if not isinstance(arg, _BaseOpt):
            continue

        # 1. Try to get value from the main spec
        value = _fetch(self.spec, arg.name)

        # 2. If not found, try the default spec
        if value is None:
            value = _fetch(self._default_spec, arg.name)

        # 3. If still None, use the option's own default
        if value is None:
            if not isinstance(arg.default, NoDefault):
                value = arg.default

        # 4. If the option is a DictOption, merge its scheme defaults
        if isinstance(arg, DictOption):
            scheme_defaults = {}
            if getattr(arg, "scheme", None):
                try:
                    scheme_defaults = arg.scheme.build_defaults()
                except Exception:
                    # If scheme defaults cannot be built, ignore
                    scheme_defaults = {}
            if isinstance(value, dict):
                # Merge: option value overrides scheme defaults
                merged = {**scheme_defaults, **value}
                value = merged
            else:
                # If value is not a dict, fall back to scheme defaults
                value = scheme_defaults

        defaults[arg.name] = value

    return defaults

