        # Option not found within the command; return None
        return None

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # Define the canonical names of arguments that silence output
    silent_names = {"quiet", "silent"}
    silent_args = []

    # Guard against None or non-iterable inputs
    if not args:
        return silent_args

    try:
        for arg in args:
            # Skip non-string items
            if not isinstance(arg, str):
                continue

            # Normalize the argument name by stripping leading dashes
            if arg.startswith("--"):
                name = arg[2:]
            elif arg.startswith("-"):
                name = arg[1:]
            else:
                name = arg

            if name in silent_names:
                silent_args.append(arg)
    except Exception:
        # In case of unexpected errors, return what we have collected so far
        pass

    return silent_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    # Ensure args is a mapping
    if args is None or not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")
    # Retrieve the list of required argument names
    try:
        required = getattr(self, "required_args")
    except AttributeError:
        raise AttributeError("The object does not define a 'required_args' attribute")
    if not isinstance(required, (list, tuple, set)):
        raise TypeError("'required_args' must be a list, tuple, or set of argument names")
    # Find any missing required arguments
    missing = [name for name in required if name not in args or args[name] is None]
    if missing:
        raise ValueError(f"Missing required argument(s): {', '.join(missing)}")
    return True

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required = []
        # Ensure args is a mapping for condition evaluation
        if not isinstance(args, dict):
            try:
                args = dict(args)
            except Exception:
                args = {}
        for opt in options_spec:
            # Each option is expected to be a mapping with at least a 'name'
            name = opt.get('name')
            if not name:
                continue
            cond = opt.get('required_when')
            if cond is None:
                continue
            try:
                if callable(cond):
                    # Callable should accept command_name and args
                    if cond(command_name, args):
                        required.append(name)
                elif isinstance(cond, str):
                    # Evaluate string condition in a restricted namespace
                    # Only allow command_name and args
                    if eval(cond, {}, {'command_name': command_name, 'args': args}):
                        required.append(name)
                else:
                    # Unsupported condition type; ignore
                    continue
            except Exception:
                # If condition evaluation fails, treat as not matched
                continue
        return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Ensure args is a mapping
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict (got {type(args).__name__})")

    # Retrieve argument specifications from parsed YAML
    spec = self.parsed_yaml.get('args', {})
    if isinstance(spec, list):
        # Convert list of single-key dicts to a mapping
        spec_map = {}
        for item in spec:
            if not isinstance(item, dict) or len(item) != 1:
                raise ValueError("Each item in args spec list must be a single-key dict")
            key, attrs = next(iter(item.items()))
            spec_map[key] = attrs
        spec = spec_map
    elif not isinstance(spec, dict):
        raise TypeError(f"args spec must be a dict or list (got {type(spec).__name__})")

    for arg_name, value in args.items():
        # Skip if no value provided
        if value is None:
            continue

        # Find the spec for this argument
        arg_spec = spec.get(arg_name)
        if not arg_spec:
            # No length constraint defined for this argument
            continue

        # Get the maximum allowed length
        max_len = arg_spec.get('length')
        if max_len is None:
            continue

        # Validate max_len type
        if not isinstance(max_len, int):
            raise TypeError(
                f"Length constraint for argument '{arg_name}' must be an integer "
                f"(got {type(max_len).__name__})"
            )
        if max_len < 0:
            raise ValueError(
                f"Length constraint for argument '{arg_name}' must be non-negative "
                f"(got {max_len})"
            )

        # Ensure the value is a sequence or mapping that supports len()
        if not hasattr(value, '__len__'):
            raise TypeError(
                f"Argument '{arg_name}' value does not support len() "
                f"(got {type(value).__name__})"
            )

        # Check the length
        if len(value) > max_len:
            raise ValueError(
                f"Argument '{arg_name}' length {len(value)} exceeds "
                f"maximum allowed {max_len}"
            )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")

    # Retrieve the argument specification that may contain 'choices' for each arg.
    # The specification is expected to be a mapping of argument names to attribute
    # dictionaries. If the specification is not present, nothing to validate.
    spec = getattr(self, "args_spec", None)
    if spec is None:
        return

    for arg_name, attrs in spec.items():
        # Skip if the attribute mapping is not a dict or does not define choices.
        if not isinstance(attrs, dict) or "choices" not in attrs:
            continue

        choices = attrs["choices"]
        # Only validate if the choices are an iterable of allowed values.
        if not isinstance(choices, (list, tuple, set)):
            continue

        # If the argument was not supplied, skip validation (requiredness is handled elsewhere).
        if arg_name not in args:
            continue

        value = args[arg_name]
        if value not in choices:
            raise ValueError(
                f"Invalid value for argument '{arg_name}': {value}. "
                f"Expected one of {choices}"
            )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is an iterable of (value, min, max) tuples
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of (value, min, max) tuples")

    for idx, item in enumerate(args):
        if not isinstance(item, (list, tuple)) or len(item) != 3:
            raise ValueError(f"Argument at index {idx} must be a tuple of (value, min, max)")

        value, min_val, max_val = item

        # Validate that min and max are comparable and min <= max
        try:
            if min_val > max_val:
                raise ValueError
        except TypeError:
            raise TypeError(f"Minimum and maximum values must be comparable for argument at index {idx}")

        # Check that value lies within the inclusive range
        try:
            if not (min_val <= value <= max_val):
                raise ValueError
        except TypeError:
            raise TypeError(f"Value and bounds must be comparable for argument at index {idx}")

    return args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict")
    if extra_vars is None:
        return vars_dict
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return vars_dict
    if not isinstance(extra_vars, (list, tuple)):
        raise TypeError("extra_vars must be a list or dict")
    for item in extra_vars:
        if isinstance(item, dict):
            vars_dict.update(item)
        else:
            raise ValueError("Each item in extra_vars must be a dict")
    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Validate playbook path
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    # Base command
    command = ['ansible-playbook', playbook_path]

    # Verbosity
    if verbose is not None:
        if not isinstance(verbose, int) or verbose < 0:
            raise ValueError("verbose must be a non‑negative integer")
        if verbose > 0:
            command.append('-' + 'v' * verbose)

    # Additional ansible-playbook arguments
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    command.append(f'--{key}')
            else:
                command.append(f'--{key}={value}')

    # Extra variables
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        command.extend(['--extra-vars', json.dumps(extra_vars)])

    # Execute the command
    try:
        result = subprocess.run(
            command,
            capture_output=True,
            text=True,
            check=False
        )
    except Exception as exc:
        raise RuntimeError(f"Failed to execute ansible-playbook: {exc}") from exc

    # Handle errors
    if result.returncode != 0:
        raise RuntimeError(
            f"Ansible playbook failed with exit code {result.returncode}:\n{result.stderr}"
        )

    return result.stdout

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dictionary")
    if not isinstance(parser_name, str):
        raise TypeError("parser_name must be a string")

    # Mapping of parser names to argument type converters.
    # Example structure:
    # {
    #     "main": {"port": int, "debug": bool},
    #     "virsh": {"timeout": float, "force": bool},
    #     ...
    # }
    type_maps = getattr(self, "_type_maps", {})

    parser_map = type_maps.get(parser_name, {})
    for key, val in list(values_dict.items()):
        if key in parser_map:
            converter = parser_map[key]
            try:
                values_dict[key] = converter(val)
            except Exception as exc:
                raise ValueError(
                    f"Could not convert argument '{key}' to {converter.__name__}"
                ) from exc
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    if not isinstance(plugin_dir, str) or not plugin_dir:
        return {}

    # Determine possible spec file names
    spec_files = ['plugin.json', 'plugin.yaml', 'plugin.yml']
    spec_path = None
    for fname in spec_files:
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            spec_path = path
            break

    if not spec_path:
        return {}

    try:
        with open(spec_path, 'r', encoding='utf-8') as f:
            if spec_path.endswith('.json'):
                data = json.load(f)
            else:
                # Try to load YAML if available
                try:
                    import yaml
                    data = yaml.safe_load(f)
                except Exception:
                    # Fallback: treat as plain text or empty
                    return {}
    except Exception:
        return {}

    if not isinstance(data, dict):
        return {}

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    # Determine the environment variable name and the default config path
    env_var = getattr(self, 'config_env_var', None)
    if env_var is None:
        raise AttributeError("Missing 'config_env_var' attribute on instance")
    if os.getenv(env_var) is None:
        config_path = getattr(self, 'config_path', None)
        if config_path is None:
            raise AttributeError("Missing 'config_path' attribute on instance")
        try:
            os.environ[env_var] = str(config_path)
        except Exception as exc:
            raise RuntimeError(f"Failed to set environment variable '{env_var}': {exc}") from exc
    return None
